const rows = $input.all();
const format = $('Webhook POST /export').first().json.body?.format || 'markdown';
const timestamp = new Date().toISOString().replace(/[:.]/g, '-').substring(0, 19);

// Regrouper par question
const questionMap = new Map();
for (const row of rows) {
  const d = row.json;
  if (!questionMap.has(d.question_id)) {
    questionMap.set(d.question_id, { ...d, responses: [] });
  }
  if (d.provider && d.reponse) {
    questionMap.get(d.question_id).responses.push({ provider: d.provider, reponse: d.reponse });
  }
}
const questions = Array.from(questionMap.values());

let content = '';
let filename = '';
let mimeType = '';

if (format === 'csv') {
  // Format CSV
  filename = `comparateur_llm_${timestamp}.csv`;
  mimeType = 'text/csv';
  content = 'question_id,date,question,temperature,provider,reponse\n';
  for (const q of questions) {
    for (const r of q.responses) {
      const escapedQ = q.question.replace(/"/g, '""');
      const escapedR = r.reponse.replace(/"/g, '""');
      content += `${q.question_id},"${q.date}","${escapedQ}",${q.temperature || ''},"${r.provider}","${escapedR}"\n`;
    }
  }
} else if (format === 'json') {
  // Format JSON
  filename = `comparateur_llm_${timestamp}.json`;
  mimeType = 'application/json';
  content = JSON.stringify({ exported_at: new Date().toISOString(), total_questions: questions.length, data: questions }, null, 2);
} else {
  // Format Markdown (défaut)
  filename = `rapport_llm_${timestamp}.md`;
  mimeType = 'text/markdown';
  content = `# Rapport Comparateur LLM\n\n`;
  content += `**Généré le** : ${new Date().toLocaleDateString('fr-FR', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' })}\n`;
  content += `**Total de questions** : ${questions.length}\n\n---\n\n`;

  for (const q of questions) {
    content += `## Question #${q.question_id}\n\n`;
    content += `**Date** : ${q.date}\n`;
    content += `**Température** : ${q.temperature || 'N/A'} | **Max tokens** : ${q.max_tokens || 'N/A'}\n\n`;
    content += `### ❓ ${q.question}\n\n`;

    for (const r of q.responses) {
      content += `#### 🤖 ${r.provider}\n\n${r.reponse}\n\n`;
    }
    content += `---\n\n`;
  }
}

return [{ json: { content, filename, mimeType, format, questionCount: questions.length } }];

const data = $('Format Content').first().json;
return [{ json: {
  success: true,
  message: `Fichier généré avec succès : ${data.filename}`,
  filename: data.filename,
  format: data.format,
  question_count: data.questionCount,
  path: `/files/exports/${data.filename}`
} }];
